import sys

def read_input():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    t = int(data[index])
    index += 1

    results = []

    for _ in range(t):
        n = int(data[index])
        index += 1

        edges = []
        for _ in range(n - 1):
            x = int(data[index])
            y = int(data[index + 1])
            edges.append((x, y))
            index += 2

        results.append(min_queries_to_identify_vertex(n, edges))

    return results

def min_queries_to_identify_vertex(n, edges):
    if n == 1:
        return 0
    elif n == 2:
        return 1
    else:
        return 2

def main():
    results = read_input()
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
